package org.fasheep.fair.core.blockchain

import io.ethers.abi.AbiFunction
import io.ethers.abi.AbiType
import org.junit.Test
import java.math.BigInteger
import kotlin.test.assertEquals

class RepositoryTest {
    @Test
    fun testRe() {
        val function = AbiFunction.parseSignature(
            "function randWithRecord(uint256 userProvidedSeed) public returns (uint256)",
        )
        val params = arrayOf(
            "11424".toBigInteger(),
        )

        val encoded = function.encodeCall(params)
        assertEquals(
            encoded.toString(),
            "0xd583e0b80000000000000000000000000000000000000000000000000000000000002ca0"
        )
    }

    @Test
    fun testStruct() {
        val function = AbiFunction(
            name = "assignRoles",
            inputs = listOf(
                AbiType.Array(AbiType.String),
                AbiType.Array(
                    AbiType.Tuple.struct(Role::class, AbiType.String, AbiType.UInt(256))
                )
            ),
            outputs = emptyList()
        )

        val params = arrayOf(
            arrayOf("1", "2", "3"),
            arrayOf(Role("A", BigInteger.ONE), Role("B", BigInteger.TWO))
        )

        val encoded = function.encodeCall(params)
        assertEquals(
            encoded.toString(),
            ""
        )
    }
}
